	assert.equal(chalk.underlineRed('foo'), '\u{1B}[58;5;1mfoo\u{1B}[59m');
	assert.equal(chalk.underlineBlackBright('foo'), '\u{1B}[58;5;8mfoo\u{1B}[59m');
